3" cy="70" r="4"/></svg><span>{{ String(index+1+(st.page-1)*6).padStart(2,'0') }}</span></div><h3>{{ doc.title }}</h3><p><span>{{ doc.nodeCount||0 }} 个节点</span><i>·</i><time>{{ date(doc.updatedAt) }}</time></p></button><button v-if="st.view==='active'" class="qgm-doc-action" type="button" :aria-label="'将文档移入回收：'+doc.title" :disabled="st.writing||!!st.pending" @click="workspace.archive(doc)"><ClientIcon name="trash"/></button><button v-else class="qgm-restore" type="button" :disabled="st.writing||!!st.pending" @click="workspace.restore(doc)">恢复这份想法 ↗</button></article></div><nav class="qgm-library-pagination" aria-label="文档分页"><button type="button" :disabled="st.listLoading||st.page<=1" @click="workspace.page(-1)">← 上一页</button><span>{{ st.page }} / {{ Math.max(1,Math.ceil(st.total/6)) }}</span><button type="button" :disabled="st.listLoading||st.page*6>=st.total" @click="workspace.page(1)">下一页 →</button></nav></dialog>
   <dialog ref="sampleDialog" class="qgm-dialog qgm-samples" aria-labelledby="qgm-samples-title" @cancel.prevent="sampleDialog?.close()"><header><div><span class="qgm-eyebrow">EVERY IDEA NEEDS A FIRST STEP</span><h2 id="qgm-samples-title">借一点起点，<em>长出自己的方向。</em></h2></div><button type="button" aria-label="关闭灵感起点" @click="sampleDialog?.close()">×</button></header><div class="qgm-sample-grid"><button v-for="(sample,index) in mindmapSamples" :key="sample.id" type="button" @click="chooseSample(sample)"><span class="qgm-sample-orb" :class="'orb-'+index" aria-hidden="true">{{ ['✳','✧','↗'][index] }}</span><small>{{ sample.tag }}</small><h3>{{ sample.name }}</h3><span>从这里开始 ↗</span></button></div><p class="qgm-dialog-note">示例只是一个文字起点，带入不调用模型，也不消耗次数。</p></dialog>
   <dialog ref="confirmDialog" class="qgm-dialog qgm-confirm" aria-labelledby="qgm-confirm-title" @cancel.prevent="st.confirm=null"><template v-if="st.confirm"><header><div><span class="qgm-eyebrow">MAKE ROOM FOR THE NEXT IDEA</span><h2 id="qgm-confirm-title">{{ st.confirm.title }}</h2></div></header><p>{{ st.confirm.body }}</p><footer><button type="button" @click="st.confirm=null">保留当前内容</button><button type="button" class="qgm-save" @click="workspace.confirm">{{ st.confirm.label }}</button></footer></template></dialog>
   <dialog ref="quoteDialog" class="qgm-dialog qgm-confirm qgm-generation-quote" aria-labelledby="qgm-quote-title" @cancel.prevent="!st.creating&&(st.quote=null)"><template v-if="st.quote"><header><div><span class="qgm-eyebrow">LET A NEW PERSPECTIVE IN</span><h2 id="qgm-quote-title">让这些线索，<em>长出新思路。</em></h2></div></header><blockquote>{{ st.quote.payload.prompt }}</blockquote><dl><div><dt>本次搭档</dt><dd>{{ st.quote.modelName||workspace.selectedModel.value?.name }}</dd></div><div><dt>本次使用</dt><dd>{{ st.quote.cost?st.quote.cost+' 次':'不扣次数' }}</dd></div><div><dt>带入线索</dt><dd>{{ st.quote.payload.context?'当前大纲，共 '+st.quote.payload.context.length+' 字符':'仅使用这次的描述' }}</dd></div></dl><p>生成结果单独保留，当前编辑内容会继续留在这里。开始后可停止等待，已发生的服务方计算不保证同步停止。</p><footer><button type="button" :disabled="st.creating" @click="st.quote=null">再想一想</button><button type="button" class="qgm-save" :disabled="st.creating" @click="workspace.generate"><QLoader v-if="st.creating" :size="18"/>{{ st.creating?'正在找回这次回执…':'确认开始生成' }}</button></footer></template></dialog>
   <dialog ref="exportDialog" class="qgm-dialog qgm-export" aria-labelledby="qgm-export-title" @cancel.prevent="cancelExport"><header><div><span class="qgm-eyebrow">GOOD IDEAS TRAVEL WELL</span><h2 id="qgm-export-title">把这份想法，<em>带到下一站。</em></h2></div><button type="button" aria-label="关闭导出面板" :disabled="exporting" @click="exportDialog?.close()">×</button></header><p>导出当前已展开的图谱；需要所有线索时，可先展开全部分支。</p><div class="qgm-export-formats"><button v-for="item in exportFormats" :key="item.id" type="button" :aria-pressed="exportFormat===item.id" :disabled="exporting" @click="exportFormat=item.id"><b>{{ item.id.toUpperCase() }}</b><strong>{{ item.name }}</strong><small>{{ item.description }}</small></button></div><fieldset v-if="exportFormat==='pdf'" class="qgm-pdf-modes" :disabled="exporting"><legend>用什么方式装好这份想法？</legend><label><input v-model="pdfMode" type="radio" value="image"/><span><b>清晰图像</b><small>保留完整画面与公式，适合分享和打印。</small></span></label><label><input v-model="pdfMode" type="radio" value="vector"/><span><b>可放大文字</b><small>保留矢量线条与可检索文字，首次需准备中文字库。</small></span></label></fieldset><p v-if="exportStatus" :role="exportError?'alert':'status'" class="qgm-export-status"><QLoader v-if="exporting" :size="20"/>{{ exportStatus }}</p><footer><button type="button" @click="cancelExport">{{ exporting?'取消导出':'留在这里' }}</button><button type="button" class="qgm-save" :disabled="exporting||!exportReady" @click="download"><ClientIcon name="download"/>{{ exporting?'正在装好这份想法…':'导出 '+exportFormat.toUpperCase() }}</button></footer></dialog>
  </Teleport>
 </section>
