<script setup>
import {computed,nextTick,onBeforeUnmount,ref,watch} from 'vue';
import {useMindmapWorkspace} from '../../composables/useMindmapWorkspace.js';
import {mindmapSamples,normalizeMindmap} from '../../lib/mindmap-outline.js';
import {exportMindmap} from '../../lib/mindmap-export.js';
import MindmapCanvas from './MindmapCanvas.vue';
import QLoader from '../QLoader.vue';
import ClientIcon from '../reference/ClientIcon.vue';
import './mindmap-workspace.css';
const workspace=useMindmapWorkspace(),st=workspace.state,canvas=ref(null),workbench=ref(null),outlineInput=ref(null),importInput=ref(null),editorTab=ref('outline'),editorVisible=ref(true),mobilePane=ref('canvas'),graphBusy=ref(true),graphError=ref(''),graphStats=ref({nodes:0,depth:0,source:''}),zoom=ref(100),folded=ref(false);
const libraryDialog=ref(null),sampleDialog=ref(null),confirmDialog=ref(null),quoteDialog=ref(null),exportDialog=ref(null),exportFormat=ref('png'),pdfMode=ref('image'),exporting=ref(false),exportStatus=ref(''),exportError=ref(false);
const cardColors=['#ab95e8','#85b9a5','#e0a18c','#9aafd4'],exportFormats=[{id:'png',name:'清晰画面',description:'适合分享与放进演示稿'},{id:'svg',name:'可放大图谱',description:'保留线条与文字结构'},{id:'pdf',name:'完整文档',description:'方便存档、阅读与打印'},{id:'html',name:'可交互图谱',description:'离线也能缩放和折叠'}];
let alive=true,exportController,opener,importRevision=0;
const canvasKey=computed(()=>workspace.auth.user?.id+':'+workspace.auth.identityRevision+':'+(st.document?.id||'new')),exportReady=computed(()=>!graphBusy.value&&!graphError.value&&graphStats.value.nodes>0&&graphStats.value.source===st.outline),taskLabel=value=>({QUEUED:'想法已进入队列',RUNNING:'正在整理新的思路',SETTLING:'结果正在保存与结算',COMPLETED:'一份新思路，已经就位。',FAILED:'这次没有完成',CANCELED:'已停止这次等待'})[value]||'状态待核对',date=value=>{const time=new Date(value);return Number.isFinite(time.getTime())?new Intl.DateTimeFormat('zh-CN',{month:'short',day:'numeric'}).format(time):'时间待核对';};
function switchEditorTab(event){if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();editorTab.value=event.key==='Home'?'outline':event.key==='End'?'assist':editorTab.value==='outline'?'assist':'outline';void nextTick(()=>document.getElementById('qgm-'+editorTab.value+'-tab')?.focus());}
function onGraphReady(value){graphStats.value=value;graphError.value='';}
function openLibrary(event){opener=event?.currentTarget;libraryDialog.value?.showModal();void workspace.loadDocuments();}
function closeLibrary(){libraryDialog.value?.close();opener?.focus?.({preventScroll:true});}
function openDocument(target){closeLibrary();workspace.requestOpen(target);mobilePane.value='canvas';}
function openSamples(){sampleDialog.value?.showModal();}
function chooseSample(sample){sampleDialog.value?.close();workspace.sample(sample);editorTab.value='outline';mobilePane.value='canvas';}
async function focusLine(line){editorVisible.value=true;editorTab.value='outline';mobilePane.value='outline';await nextTick();const input=outlineInput.value;if(!input)return;const lines=st.outline.split('\n'),start=lines.slice(0,line).join('\n').length+(line>0?1:0);input.focus();input.setSelectionRange(start,start+(lines[line]?.length||0));}
async function copyOutline(){const user=workspace.auth.user?.id,identity=workspace.auth.identityRevision,valid=()=>alive&&workspace.auth.user?.id===user&&workspace.auth.identityRevision===identity;try{await navigator.clipboard.writeText(st.outline);if(valid())st.notice='大纲已复制，带去下一个灵感发生的地方吧。';}catch{if(valid())st.error='暂时没有复制成功，可以在大纲里选择文字后复制。';}}
async function importOutline(event){const file=event.target.files?.[0];event.target.value='';if(!file)return;if(!/\.(md|markdown|txt)$/i.test(file.name)){st.error='请选择文字或 Markdown 大纲文件。';return;}if(file.size>256000){st.error='这份文字文件较大，请拆分为较短的大纲后再导入。';return;}const revision=++importRevision,user=workspace.auth.user?.id,identity=workspace.auth.identityRevision;try{const text=normalizeMindmap((await(file.text?file.text():new Promise((done,reject)=>{const reader=new window.FileReader();reader.onload=()=>done(String(reader.result));reader.onerror=reject;reader.readAsText(file,'utf-8');}))).replace(/^\uFEFF/,''));if(!alive||revision!==importRevision||user!==workspace.auth.user?.id||identity!==workspace.auth.identityRevision)return;workspace.sample({title:file.name.replace(/\.(md|markdown|txt)$/i,'').slice(0,100),outline:text});editorTab.value='outline';editorVisible.value=true;}catch(cause){if(alive&&revision===importRevision)st.error=cause.message||'文件暂未读取，当前大纲仍然保留。';}}
async function toggleFold(){folded.value=!folded.value;await canvas.value?.fold(folded.value);}
async function fullscreen(){try{if(document.fullscreenElement)await document.exitFullscreen();else if(workbench.value?.requestFullscreen)await workbench.value.requestFullscreen();else st.notice='当前环境暂不支持全屏，可以收起编辑面板，留出更大的画布。';}catch{st.notice='全屏暂未打开，可以收起编辑面板继续查看。';}}
function openExport(){if(!exportReady.value)return;exportStatus.value='';exportError.value=false;exportDialog.value?.showModal();}
function cancelExport(){if(exporting.value){exportController?.abort();exportStatus.value='已取消导出，文档与画布保持原样。';}else exportDialog.value?.close();}
async function download(){if(!exportReady.value||exporting.value)return;const user=workspace.auth.user?.id,identity=workspace.auth.identityRevision,previousPane=mobilePane.value;exporting.value=true;exportError.value=false;exportStatus.value='正在准备这份想法…';exportController=new AbortController();try{mobilePane.value='canvas';await nextTick();await canvas.value.prepare();if(exportController.signal.aborted||!alive||workspace.auth.user?.id!==user||workspace.auth.identityRevision!==identity)throw new DOMException('导出已取消','AbortError');const result=await exportMindmap(canvas.value.snapshot(),exportFormat.value,{title:st.title||graphStats.value.title,pdfMode:pdfMode.value,signal:exportController.signal,onProgress:value=>{if(alive&&workspace.auth.user?.id===user&&workspace.auth.identityRevision===identity)exportStatus.value=value;}});if(alive&&workspace.auth.user?.id===user&&workspace.auth.identityRevision===identity)exportStatus.value=result.note||'已导出 '+result.format.toUpperCase()+'，这份想法可以去更远的地方了。';}catch(cause){if(alive&&workspace.auth.user?.id===user&&workspace.auth.identityRevision===identity){exportError.value=cause.name!=='AbortError';exportStatus.value=cause.name==='AbortError'?'已取消导出，文字与画布仍然保留。':cause.message||'这次导出尚未完成，请稍后重试。';}}finally{if(alive&&workspace.auth.user?.id===user&&workspace.auth.identityRevision===identity){exporting.value=false;mobilePane.value=previousPane;}}}
function historyToggle(event){if(event.target.open)void workspace.loadGenerations();}
watch([exportFormat,pdfMode],()=>{if(!exporting.value){exportStatus.value='';exportError.value=false;}});
watch(()=>st.confirm,async value=>{await nextTick();if(!alive)return;if(value&&!confirmDialog.value?.open)confirmDialog.value?.showModal();else if(!value)confirmDialog.value?.close();});
watch(()=>st.quote,async value=>{await nextTick();if(!alive)return;if(value&&!quoteDialog.value?.open)quoteDialog.value?.showModal();else if(!value)quoteDialog.value?.close();});
watch([()=>workspace.auth.user?.id,()=>workspace.auth.identityRevision],()=>{importRevision++;exportController?.abort();exporting.value=false;exportStatus.value='';for(const dialog of[libraryDialog,sampleDialog,confirmDialog,quoteDialog,exportDialog])dialog.value?.close();graphStats.value={nodes:0,depth:0,source:''};graphError.value='';});
onBeforeUnmount(()=>{alive=false;importRevision++;exportController?.abort();});
</script>
